-- ============================================================================
-- Vitalis Health Group - Marketing - BigQuery
-- Marketing data for Vitalis Health Group: web analytics in the style of
-- Google Analytics 4, campaigns, ad spend, leads, email and consent. Every
-- company's marketing data has the same structure, in its own dataset.
-- Generated by data/generator (make data). Run the whole file top to bottom;
-- it can be re-run and replaces the tables each time.
-- Dates are relative to the day the script runs, so 'today' and 'this month'
-- always have data. All people, companies and identifiers are fictional.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Setup
-- Datasets are created in the project selected in the BigQuery console,
-- in the project's default location.
-- ----------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS vitalis_marketing
OPTIONS (description = 'Vitalis Health Group Marketing');

-- ============================================================================
-- Vitalis Health Group Marketing (vitalis_marketing)
-- Marketing and web analytics data for Vitalis Health Group.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Bronze: raw extracts from the source systems, loaded as-is.
-- ----------------------------------------------------------------------------

-- bronze_campaigns: Marketing campaigns from the campaign planning tool.
--   Rows: 20

CREATE OR REPLACE TABLE vitalis_marketing.bronze_campaigns (
  campaign_id STRING,
  campaign_name STRING,
  channel STRING,
  product_code STRING,
  start_date DATE,
  end_date DATE,
  budget_aud NUMERIC(12,2),
  target_region STRING,
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Marketing campaigns from the campaign planning tool.');


-- bronze_ad_spend: Daily impressions, clicks and cost per campaign from the ad
-- platforms.
--   Rows: 600

CREATE OR REPLACE TABLE vitalis_marketing.bronze_ad_spend (
  campaign_id STRING,
  spend_date DATE,
  impressions INT64,
  clicks INT64,
  cost_aud NUMERIC(12,2),
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Daily impressions, clicks and cost per campaign from the ad platforms.');


-- bronze_web_sessions: Web sessions from the analytics export (GA4 style).
-- Country spellings vary.
--   Columns of note:
--     user_pseudo_id: Pseudonymous device identifier
--     ip_address: PII: IP address
--   Rows: 480

CREATE OR REPLACE TABLE vitalis_marketing.bronze_web_sessions (
  session_id STRING,
  user_pseudo_id STRING OPTIONS (description = 'Pseudonymous device identifier'),
  session_start TIMESTAMP,
  landing_page STRING,
  traffic_source STRING,
  traffic_medium STRING,
  campaign_id STRING,
  device_category STRING,
  browser STRING,
  country STRING,
  city STRING,
  ip_address STRING OPTIONS (description = 'PII: IP address'),
  is_engaged BOOL,
  pageviews INT64,
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Web sessions from the analytics export (GA4 style). Country spellings vary.');


-- bronze_web_events: Web events from the analytics export. event_params is the
-- raw JSON payload.
--   Columns of note:
--     user_pseudo_id: Pseudonymous device identifier
--     event_params: Raw JSON: product, page title, form, calculator and
--       application amounts
--   Rows: 989

CREATE OR REPLACE TABLE vitalis_marketing.bronze_web_events (
  event_id STRING,
  session_id STRING,
  user_pseudo_id STRING OPTIONS (description = 'Pseudonymous device identifier'),
  event_ts TIMESTAMP,
  event_name STRING,
  page_path STRING,
  event_params STRING OPTIONS (description = 'Raw JSON: product, page title, form, calculator and application amounts'),
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Web events from the analytics export. event_params is the raw JSON payload.');


-- bronze_leads: Contact-me form submissions from the web site. Names and
-- emails are as typed.
--   Columns of note:
--     first_name: Person name
--     last_name: Person name
--     email: PII: email
--     phone: PII: phone number
--     message: Free text: often contains phone numbers, emails and suburbs
--   Rows: 102

CREATE OR REPLACE TABLE vitalis_marketing.bronze_leads (
  lead_id STRING,
  session_id STRING,
  submitted_at TIMESTAMP,
  first_name STRING OPTIONS (description = 'Person name'),
  last_name STRING OPTIONS (description = 'Person name'),
  email STRING OPTIONS (description = 'PII: email'),
  phone STRING OPTIONS (description = 'PII: phone number'),
  country STRING,
  product_code STRING,
  message STRING OPTIONS (description = 'Free text: often contains phone numbers, emails and suburbs'),
  marketing_consent BOOL,
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Contact-me form submissions from the web site. Names and emails are as typed.');


-- bronze_email_sends: Marketing emails sent, opened and clicked, from the
-- email platform.
--   Columns of note:
--     email: PII: email
--   Rows: 500

CREATE OR REPLACE TABLE vitalis_marketing.bronze_email_sends (
  send_id STRING,
  campaign_id STRING,
  email STRING OPTIONS (description = 'PII: email'),
  sent_at TIMESTAMP,
  opened BOOL,
  clicked BOOL,
  unsubscribed BOOL,
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Marketing emails sent, opened and clicked, from the email platform.');


-- bronze_consents: Marketing consent changes from the preference centre: one
-- row per change.
--   Columns of note:
--     email: PII: email
--   Rows: 267

CREATE OR REPLACE TABLE vitalis_marketing.bronze_consents (
  consent_id STRING,
  email STRING OPTIONS (description = 'PII: email'),
  consent_type STRING,
  granted BOOL,
  recorded_at TIMESTAMP,
  capture_source STRING,
  _source_system STRING,
  _batch_id STRING
)
OPTIONS (description = 'Marketing consent changes from the preference centre: one row per change.');


-- ----------------------------------------------------------------------------
-- Silver: cleaned, typed and conformed. Built from bronze.
-- ----------------------------------------------------------------------------

-- silver_campaigns: Campaigns.

CREATE OR REPLACE TABLE vitalis_marketing.silver_campaigns
OPTIONS (description = 'Campaigns.')
AS
SELECT campaign_id, campaign_name, channel, product_code, start_date, end_date, budget_aud, target_region
FROM vitalis_marketing.bronze_campaigns;

-- silver_ad_spend: Daily ad spend per campaign.

CREATE OR REPLACE TABLE vitalis_marketing.silver_ad_spend
OPTIONS (description = 'Daily ad spend per campaign.')
AS
SELECT campaign_id, spend_date, impressions, clicks, cost_aud
FROM vitalis_marketing.bronze_ad_spend;

-- silver_web_sessions: Web sessions with clean country codes, region and
-- session date.

CREATE OR REPLACE TABLE vitalis_marketing.silver_web_sessions
OPTIONS (description = 'Web sessions with clean country codes, region and session date.')
AS
WITH base AS (
  SELECT
    session_id,
    user_pseudo_id,
    session_start,
    CAST(session_start AS DATE) AS session_date,
    landing_page,
    traffic_source,
    traffic_medium,
    campaign_id,
    device_category,
    browser,
    CASE WHEN UPPER(TRIM(country)) IN ('AU', 'AUS', 'AUSTRALIA') THEN 'AU' WHEN UPPER(TRIM(country)) IN ('NZ', 'NZL', 'NEW ZEALAND') THEN 'NZ' WHEN UPPER(TRIM(country)) IN ('SG', 'SGP', 'SINGAPORE') THEN 'SG' WHEN UPPER(TRIM(country)) IN ('GB', 'GBR', 'UK', 'UNITED KINGDOM') THEN 'GB' WHEN UPPER(TRIM(country)) IN ('US', 'USA', 'UNITED STATES') THEN 'US' ELSE UPPER(TRIM(country)) END AS country,
    city,
    ip_address,
    is_engaged,
    pageviews
  FROM vitalis_marketing.bronze_web_sessions
)
SELECT base.*, CASE WHEN base.country IN ('AU', 'NZ', 'SG', 'JP', 'IN', 'MY', 'ID', 'HK') THEN 'APAC' WHEN base.country IN ('GB', 'IE', 'DE', 'FR', 'NL', 'AE', 'ZA') THEN 'EMEA' WHEN base.country IN ('US', 'CA', 'MX', 'BR') THEN 'AMER' ELSE 'UNKNOWN' END AS region
FROM base;

-- silver_web_events: Web events with the JSON parameters parsed into columns,
-- and session attribution.

CREATE OR REPLACE TABLE vitalis_marketing.silver_web_events
OPTIONS (description = 'Web events with the JSON parameters parsed into columns, and session attribution.')
AS
SELECT
  e.event_id,
  e.session_id,
  e.user_pseudo_id,
  e.event_ts,
  CAST(e.event_ts AS DATE) AS event_date,
  e.event_name,
  e.page_path,
  JSON_VALUE(e.event_params, '$.product') AS product_code,
  JSON_VALUE(e.event_params, '$.form_name') AS form_name,
  CAST(JSON_VALUE(e.event_params, '$.calculator_amount') AS NUMERIC) AS calculator_amount,
  CAST(JSON_VALUE(e.event_params, '$.application_value') AS NUMERIC) AS application_value,
  s.campaign_id,
  s.traffic_source,
  s.traffic_medium,
  s.country,
  s.region
FROM vitalis_marketing.bronze_web_events e
JOIN vitalis_marketing.silver_web_sessions s ON s.session_id = e.session_id;

-- silver_leads: Leads with tidied names and emails, campaign attribution and
-- region.

CREATE OR REPLACE TABLE vitalis_marketing.silver_leads
OPTIONS (description = 'Leads with tidied names and emails, campaign attribution and region.')
AS
SELECT
  l.lead_id,
  l.session_id,
  l.submitted_at,
  CAST(l.submitted_at AS DATE) AS submitted_date,
  INITCAP(TRIM(l.first_name)) AS first_name,
  INITCAP(TRIM(l.last_name)) AS last_name,
  LOWER(TRIM(l.email)) AS email,
  l.phone,
  l.product_code,
  l.message,
  l.marketing_consent,
  s.campaign_id,
  s.traffic_source,
  s.traffic_medium,
  s.country,
  s.region
FROM vitalis_marketing.bronze_leads l
JOIN vitalis_marketing.silver_web_sessions s ON s.session_id = l.session_id;

-- silver_email_sends: Email sends with campaign and product.

CREATE OR REPLACE TABLE vitalis_marketing.silver_email_sends
OPTIONS (description = 'Email sends with campaign and product.')
AS
SELECT
  e.send_id,
  e.campaign_id,
  c.campaign_name,
  c.product_code,
  LOWER(e.email) AS email,
  e.sent_at,
  CAST(e.sent_at AS DATE) AS sent_date,
  e.opened,
  e.clicked,
  e.unsubscribed
FROM vitalis_marketing.bronze_email_sends e
LEFT JOIN vitalis_marketing.silver_campaigns c ON c.campaign_id = e.campaign_id;

-- silver_consents: Consent history; is_current marks the latest choice per
-- email and consent type.

CREATE OR REPLACE TABLE vitalis_marketing.silver_consents
OPTIONS (description = 'Consent history; is_current marks the latest choice per email and consent type.')
AS
WITH ranked AS (
  SELECT c.*, ROW_NUMBER() OVER (PARTITION BY LOWER(c.email), c.consent_type ORDER BY c.recorded_at DESC) AS rn
  FROM vitalis_marketing.bronze_consents c
)
SELECT
  consent_id,
  LOWER(email) AS email,
  consent_type,
  granted,
  recorded_at,
  capture_source,
  CASE WHEN rn = 1 THEN TRUE ELSE FALSE END AS is_current
FROM ranked;

-- ----------------------------------------------------------------------------
-- Gold: business-ready data products for reporting and AI. Built from silver.
-- ----------------------------------------------------------------------------

-- gold_campaign_performance: Spend, reach, leads, applications and cost per
-- lead and application, per campaign.

CREATE OR REPLACE TABLE vitalis_marketing.gold_campaign_performance
OPTIONS (description = 'Spend, reach, leads, applications and cost per lead and application, per campaign.')
AS
WITH spend AS (
  SELECT campaign_id, SUM(impressions) AS impressions, SUM(clicks) AS clicks, SUM(cost_aud) AS cost_aud
  FROM vitalis_marketing.silver_ad_spend
  GROUP BY campaign_id
),
sessions AS (
  SELECT campaign_id, COUNT(*) AS sessions FROM vitalis_marketing.silver_web_sessions GROUP BY campaign_id
),
leads AS (
  SELECT campaign_id, COUNT(*) AS leads FROM vitalis_marketing.silver_leads GROUP BY campaign_id
),
applications AS (
  SELECT campaign_id, COUNT(*) AS applications, SUM(application_value) AS application_value
  FROM vitalis_marketing.silver_web_events
  WHERE event_name = 'apply_complete'
  GROUP BY campaign_id
)
SELECT
  c.campaign_id,
  c.campaign_name,
  c.channel,
  c.product_code,
  c.target_region,
  c.start_date,
  c.end_date,
  c.budget_aud,
  COALESCE(sp.cost_aud, 0) AS spend_aud,
  COALESCE(sp.impressions, 0) AS impressions,
  COALESCE(sp.clicks, 0) AS clicks,
  ROUND(CAST(sp.clicks AS NUMERIC) * 100 / NULLIF(sp.impressions, 0), 1) AS click_through_rate_pct,
  COALESCE(se.sessions, 0) AS sessions,
  COALESCE(l.leads, 0) AS leads,
  COALESCE(a.applications, 0) AS applications,
  COALESCE(a.application_value, 0) AS application_value_aud,
  ROUND(CAST(sp.cost_aud / NULLIF(l.leads, 0) AS NUMERIC), 2) AS cost_per_lead_aud,
  ROUND(CAST(sp.cost_aud / NULLIF(a.applications, 0) AS NUMERIC), 2) AS cost_per_application_aud
FROM vitalis_marketing.silver_campaigns c
LEFT JOIN spend sp ON sp.campaign_id = c.campaign_id
LEFT JOIN sessions se ON se.campaign_id = c.campaign_id
LEFT JOIN leads l ON l.campaign_id = c.campaign_id
LEFT JOIN applications a ON a.campaign_id = c.campaign_id;

-- gold_funnel_daily: Daily web funnel by product and region: sessions,
-- calculator uses, forms and applications.

CREATE OR REPLACE TABLE vitalis_marketing.gold_funnel_daily
OPTIONS (description = 'Daily web funnel by product and region: sessions, calculator uses, forms and applications.')
AS
SELECT
  event_date,
  product_code,
  region,
  COUNT(DISTINCT session_id) AS sessions,
  SUM(CASE WHEN event_name = 'calculator_used' THEN 1 ELSE 0 END) AS calculator_uses,
  SUM(CASE WHEN event_name = 'form_start' THEN 1 ELSE 0 END) AS form_starts,
  SUM(CASE WHEN event_name = 'form_submit' THEN 1 ELSE 0 END) AS form_submits,
  SUM(CASE WHEN event_name = 'apply_start' THEN 1 ELSE 0 END) AS application_starts,
  SUM(CASE WHEN event_name = 'apply_complete' THEN 1 ELSE 0 END) AS applications_completed
FROM vitalis_marketing.silver_web_events
GROUP BY 1, 2, 3;

-- gold_channel_performance: Sessions, leads, applications and conversion rate
-- by traffic source, medium and region.

CREATE OR REPLACE TABLE vitalis_marketing.gold_channel_performance
OPTIONS (description = 'Sessions, leads, applications and conversion rate by traffic source, medium and region.')
AS
WITH conversions AS (
  SELECT session_id, MAX(CASE WHEN event_name = 'apply_complete' THEN 1 ELSE 0 END) AS converted
  FROM vitalis_marketing.silver_web_events
  GROUP BY session_id
),
leads AS (
  SELECT session_id, COUNT(*) AS leads FROM vitalis_marketing.silver_leads GROUP BY session_id
)
SELECT
  ws.traffic_source,
  ws.traffic_medium,
  ws.region,
  COUNT(*) AS sessions,
  SUM(CASE WHEN ws.is_engaged THEN 1 ELSE 0 END) AS engaged_sessions,
  SUM(COALESCE(l.leads, 0)) AS leads,
  SUM(COALESCE(c.converted, 0)) AS applications,
  ROUND(CAST(SUM(COALESCE(c.converted, 0)) AS NUMERIC) * 100 / NULLIF(COUNT(*), 0), 1) AS conversion_rate_pct
FROM vitalis_marketing.silver_web_sessions ws
LEFT JOIN conversions c ON c.session_id = ws.session_id
LEFT JOIN leads l ON l.session_id = ws.session_id
GROUP BY 1, 2, 3;
